#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_repeat.h"

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;

at::Tensor repeat(const at::Tensor &self, at::IntArrayRef repeats)
{
    // ---- 输入校验 ----
    TORCH_CHECK(self.scalar_type() == at::kHalf || self.scalar_type() == at::kFloat || self.scalar_type() == at::kBFloat16,
                "repeat: only float16, bfloat16 and float32 are supported, got ", self.scalar_type());
    TORCH_CHECK(self.is_contiguous(), "repeat: input tensor must be contiguous");
    TORCH_CHECK(static_cast<int64_t>(repeats.size()) == self.dim(),
                "repeat: repeats must have the same number of dimensions as input");

    // ---- 计算输出形状 ----
    auto inputSizes = self.sizes();
    std::vector<int64_t> outputSizes;
    for (size_t i = 0; i < repeats.size(); ++i) {
        outputSizes.push_back(inputSizes[i] * repeats[i]);
    }

    at::Tensor output = at::empty(outputSizes, self.options());

    int64_t inputTotalLength = self.numel();
    int64_t outputTotalLength = output.numel();

    if (outputTotalLength == 0) {
        return output;
    }

    int64_t dtypeSize = self.element_size();

    // ---- 获取硬件参数 ----
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- Block 级 tiling (核间切分, Cache Line 对齐) ----
    // 按输出总元素数切分
    int64_t totalLength = outputTotalLength;
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalLength - formerNum * formerLength;

    // ---- UB 级 tiling (核内切分) ----
    // bufferCoefficient = 每元素在 UB 中总占用字节
    // 单输入单输出 + double buffer: 2 queues * 2(double buf) * dtypeSize = 4 * dtypeSize
    int64_t bufferCoefficient = dtypeSize * 4;
    if (bufferCoefficient == 0) { bufferCoefficient = 1; }
    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
    if (dtypeSize == 0) { dtypeSize = 1; }
    int64_t alignElements = 32 / dtypeSize;
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;

    // 确保 tileLength 不超过 blockLength 的最小值
    if (tileLength < alignElements) {
        tileLength = alignElements;
    }

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    // ---- 所有参数必须是左值 ----
    int64_t inputTotalLengthLval = inputTotalLength;
    int64_t outputTotalLengthLval = outputTotalLength;
    int64_t formerNumLval = formerNum;
    int64_t formerLengthLval = formerLength;
    int64_t tailLengthLval = tailLength;
    int64_t tileLengthLval = tileLength;
    int64_t dtypeSizeLval = dtypeSize;

    EXEC_KERNEL_CMD(repeat, blockDim,
                    self, output,
                    inputTotalLengthLval, outputTotalLengthLval,
                    formerNumLval, formerLengthLval, tailLengthLval, tileLengthLval, dtypeSizeLval);

    return output;
}

}  // namespace ascend_kernel
