from pathlib import Path

import torch
import torch.nn as nn

_KERNEL_BUILD = Path(__file__).resolve().parent / "kernel" / "build"
_LIB_PATTERN = str(_KERNEL_BUILD / "repeat_ext*")

# 优先 whl import（触发 TORCH_LIBRARY 注册）
try:
    import repeat_ext  # noqa: F401
except ImportError:
    # 兜底：直加载 .so
    if _LIB_PATTERN not in "".join(sys.path):
        import glob as _glob
        _libs = _glob.glob(_LIB_PATTERN)
        if _libs:
            torch.ops.load_library(_libs[0])


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, x: torch.Tensor, repeats: tuple):
        # 输入校验
        assert x.dtype in (torch.float16, torch.float32, torch.bfloat16)
        assert x.is_contiguous()
        assert len(repeats) == x.dim()

        # 调用注册的 AscendC 算子
        return torch.ops.npu.repeat(x, repeats)
