15	template <typename T>
16	class KernelRepeat {
17	public:
18	    __aicore__ inline KernelRepeat() {}
19	
20	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
21	                                int64_t inputTotalLength, int64_t outputTotalLength,
22	                                int64_t formerNum, int64_t formerLength,
