25	        int64_t blockIdx = AscendC::GetBlockIdx();
26	
27	        this->inputTotalLength = inputTotalLength;
28	        this->outputTotalLength = outputTotalLength;
29	
30	        if (blockIdx < formerNum) {
31	            this->blockLength = formerLength;
32	            int64_t offset = formerLength * blockIdx;
33	            xGm.SetGlobalBuffer((__gm__ T *)x, inputTotalLength);
34	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
35	            this->outOffset = offset;
36	        } else {
37	            this->blockLength = tailLength;
38	            int64_t tailIdx = blockIdx - formerNum;
39	            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
40	            xGm.SetGlobalBuffer((__gm__ T *)x, inputTotalLength);
41	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
42	            this->outOffset = offset;
43	        }
44	
45	        this->tileLength = tileLength;
46	
47	        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
48	        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));
49	    }
50	
51	    __aicore__ inline void Process()
52	    {
53	        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
54	        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
55	
56	        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
57	        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;
58	
59	        for (int64_t i = 0; i < tileNum - 1; ++i) {
60	            CopyIn(i, this->tileLength);
61	            Compute(i, this->tileLength);
62	            CopyOut(i, this->tileLength);
63	        }
64	        if (tileNum > 0) {
65	            CopyIn(tileNum - 1, alignedTailLen);
66	            Compute(tileNum - 1, alignedTailLen);
67	            CopyOut(tileNum - 1, alignedTailLen);
68	        }
69	    }
70	
71	private:
72	    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
73	    {
74	        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
75	
76	        // 计算当前 tile 在输出中的全局偏移
77	        int64_t globalOutOffset = this->outOffset + progress * this->tileLength;
78	        // 计算对应的输入偏移（循环模式）
79	        int64_t inputOffset = globalOutOffset % this->inputTotalLength;
80	
81	        // 如果当前 tile 跨越了输入边界，需要分两段读取
82	        int64_t remainingInInput = this->inputTotalLength - inputOffset;
83	
84	        if (remainingInInput >= curTileLength) {
85	            // 不需要跨越边界，一次性读取
86	            AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
87	            AscendC::DataCopyPadExtParams<T> padParams{false, 0, 0, 0};
88	            AscendC::DataCopyPad(xLocal, xGm[inputOffset], copyParams, padParams);
89	        } else {
90	            // 需要跨越输入边界，先读第一段
91	            AscendC::DataCopyExtParams copyParams1{1, static_cast<uint32_t>(remainingInInput * sizeof(T)), 0, 0, 0};
92	            AscendC::DataCopyPadExtParams<T> padParams1{false, 0, 0, 0};
93	            AscendC::DataCopyPad(xLocal, xGm[inputOffset], copyParams1, padParams1);
94	
95	            // 再读第二段（从输入开头）
96	            int64_t secondLen = curTileLength - remainingInInput;
97	            AscendC::DataCopyExtParams copyParams2{1, static_cast<uint32_t>(secondLen * sizeof(T)), 0, 0, 0};
98	            AscendC::DataCopyPadExtParams<T> padParams2{false, 0, 0, 0};
99	            AscendC::DataCopyPad(xLocal[remainingInInput], xGm[0], copyParams2, padParams2);
100	        }
101	
102	        inQueueX.EnQue(xLocal);
103	    }
104	
105	    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
106	    {
107	        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
108	        AscendC::LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();
109	
110	        // Repeat 是数据搬运操作，无需数值计算
111	        // 直接将输入数据复制到输出
112	        AscendC::DataCopy(yLocal, xLocal, curTileLength);
113	
114	        outQueueY.EnQue<T>(yLocal);
115	        inQueueX.FreeTensor(xLocal);
116	    }
117	
118	    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
119	    {
120	        AscendC::LocalTensor<T> yLocal = outQueueY.DeQue<T>();
121	
122	        int64_t globalOutOffset = this->outOffset + progress * this->tileLength;
123	        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
124	        AscendC::DataCopyPad(yGm[globalOutOffset], yLocal, copyParams);
125	
126	        outQueueY.FreeTensor(yLocal);
127	    }
128	
129	private:
130	    AscendC::TPipe pipe;
131	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
132	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
133	    AscendC::GlobalTensor<T> xGm;
134	    AscendC::GlobalTensor<T> yGm;
135	    int64_t blockLength;
136	    int64_t tileLength;
137	    int64_t inputTotalLength;
138	    int64_t outputTotalLength;
139	    int64_t outOffset;
140	};
