15	namespace ascend_kernel {
16	
17	constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
18	
19	at::Tensor repeat(const at::Tensor &self, at::IntArrayRef repeats)
20	{
21	    // ---- 输入校验 ----
22	    TORCH_CHECK(self.scalar_type() == at::kHalf || self.scalar_type() == at::kFloat || self.scalar_type() == at::kBFloat16,
23	                "repeat: only float16, bfloat16 and float32 are supported, got ", self.scalar_type());
24	    TORCH_CHECK(self.is_contiguous(), "repeat: input tensor must be contiguous");
25	    TORCH_CHECK(static_cast<int64_t>(repeats.size()) == self.dim(),
26	                "repeat: repeats must have the same number of dimensions as input");
27	
28	    // ---- 计算输出形状 ----
29	    auto inputSizes = self.sizes();
30	    std::vector<int64_t> outputSizes;
31	    for (size_t i = 0; i < repeats.size(); ++i) {
32	        outputSizes.push_back(inputSizes[i] * repeats[i]);
33	    }
34	
35	    at::Tensor output = at::empty(outputSizes, self.options());
36	
37	    int64_t inputTotalLength = self.numel();
38	    int64_t outputTotalLength = output.numel();
39	
40	    if (outputTotalLength == 0) {
41	        return output;
42	    }
43	
44	    int64_t dtypeSize = self.element_size();
45	
46	    // ---- 获取硬件参数 ----
47	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
48	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
49	    uint64_t ubSize;
50	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
51	    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);
52	
53	    // ---- Block 级 tiling (核间切分, Cache Line 对齐) ----
54	    // 按输出总元素数切分
55	    int64_t totalLength = outputTotalLength;
56	    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
57	    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
58	                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;
59	
60	    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
61	    int64_t formerNum = usedCoreNum - 1;
62	    int64_t formerLength = totalLengthCoreAlign;
63	    int64_t tailLength = totalLength - formerNum * formerLength;
64	
65	    // ---- UB 级 tiling (核内切分) ----
66	    // bufferCoefficient = 每元素在 UB 中总占用字节
67	    // 单输入单输出 + double buffer: 2 queues * 2(double buf) * dtypeSize = 4 * dtypeSize
68	    int64_t bufferCoefficient = dtypeSize * 4;
69	    if (bufferCoefficient == 0) { bufferCoefficient = 1; }
70	    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
71	    if (dtypeSize == 0) { dtypeSize = 1; }
72	    int64_t alignElements = 32 / dtypeSize;
73	    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
74	
75	    // 确保 tileLength 不超过 blockLength 的最小值
76	    if (tileLength < alignElements) {
77	        tileLength = alignElements;
78	    }
79	
80	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
81	
82	    // ---- 所有参数必须是左值 ----
83	    int64_t inputTotalLengthLval = inputTotalLength;
84	    int64_t outputTotalLengthLval = outputTotalLength;
85	    int64_t formerNumLval = formerNum;
86	    int64_t formerLengthLval = formerLength;
87	    int64_t tailLengthLval = tailLength;
88	    int64_t tileLengthLval = tileLength;
89	    int64_t dtypeSizeLval = dtypeSize;
90	
91	    EXEC_KERNEL_CMD(repeat, blockDim,
92	                    self, output,
93	                    inputTotalLengthLval, outputTotalLengthLval,
94	                    formerNumLval, formerLengthLval, tailLengthLval, tileLengthLval, dtypeSizeLval);
95	
96	    return output;
97	}
98	
99	}  // namespace ascend_kernel
