53	    // ---- Block 级 tiling (核间切分, 32字节对齐) ----
54	    // 按输出总元素数切分，确保每个核处理的数据量是 32字节对齐的
55	    int64_t totalLength = outputTotalLength;
56	    int64_t alignElements = 32 / dtypeSize;
57	    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
58	    // 向上对齐到 alignElements 的倍数（确保 32字节对齐）
59	    int64_t totalLengthCoreAlign = ((totalLengthCore + alignElements - 1) / alignElements) * alignElements;
