95	
96	    // ---- 所有参数必须是左值 ----
97	    int64_t inputTotalLengthLval = inputTotalLength;
98	    int64_t outputTotalLengthLval = outputTotalLength;
99	    int64_t formerNumLval = formerNum;
100	    int64_t formerLengthLval = formerLength;
101	    int64_t tailLengthLval = tailLength;
102	    int64_t tileLengthLval = tileLength;
103	    int64_t dtypeSizeLval = dtypeSize;
104	
105	    EXEC_KERNEL_CMD(repeat, blockDim,
106	                    self, output,
107	                    inputTotalLengthLval, outputTotalLengthLval,
108	                    formerNumLval, formerLengthLval, tailLengthLval, tileLengthLval, dtypeSizeLval);
109	
110	    return output;
