15	namespace ascend_kernel {
16	
17	constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
18	
19	at::Tensor repeat(const at::Tensor &self, at::IntArrayRef repeats)
20	{
21	    // ---- 输入校验 ----
22	    TORCH_CHECK(self.scalar_type() == at::kHalf || self.scalar_type() == at::kFloat || self.scalar_type() == at::kBFloat16,
23	                "repeat: only float16, bfloat16 and float32 are supported, got ", self.scalar_type());
24	    TORCH_CHECK(self.is_contiguous(), "repeat: input tensor must be contiguous");
25	    TORCH_CHECK(static_cast<int64_t>(repeats.size()) == self.dim(),
26	                "repeat: repeats must have the same number of dimensions as input");
27	
28	    // ---- 计算输出形状 ----
29	    auto inputSizes = self.sizes();
30	    std::vector<int64_t> outputSizes;
31	    for (size_t i = 0; i < repeats.size(); ++i) {
32	        outputSizes.push_back(inputSizes[i] * repeats[i]);
33	    }
34	
35	    at::Tensor output = at::empty(outputSizes, self.options());
36	
37	    int64_t inputTotalLength = self.numel();
38	    int64_t outputTotalLength = output.numel();
39	
40	    if (outputTotalLength == 0) {
41	        return output;
42	    }
43	
44	    int64_t dtypeSize = self.element_size();
45	
46	    // ---- 获取硬件参数 ----
47	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
48	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
49	    uint64_t ubSize;
50	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
51	    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);
52	
53	    // ---- Block 级 tiling (核间切分, 32字节对齐) ----
54	    // 按输出总元素数切分，确保每个核处理的数据量是 32字节对齐的
55	    int64_t totalLength = outputTotalLength;
56	    int64_t alignElements = 32 / dtypeSize;
57	    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
58	    // 向上对齐到 alignElements 的倍数（确保 32字节对齐）
59	    int64_t totalLengthCoreAlign = ((totalLengthCore + alignElements - 1) / alignElements) * alignElements;
60	    // 同时确保至少 512 字节（Cache Line）
61	    int64_t cacheLineElements = CACHE_LINE_BYTE_LENGTH / dtypeSize;
62	    if (totalLengthCoreAlign < cacheLineElements) {
63	        totalLengthCoreAlign = ((totalLengthCoreAlign + cacheLineElements - 1) / cacheLineElements) * cacheLineElements;
64	    }
65	
66	    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
67	    int64_t formerNum = usedCoreNum - 1;
68	    int64_t formerLength = totalLengthCoreAlign;
69	    int64_t tailLength = totalLength - formerNum * formerLength;
70	    // 确保 tailLength 也是 alignElements 的倍数
71	    if (tailLength % alignElements != 0) {
72	        tailLength = (tailLength / alignElements) * alignElements;
73	    }
74	    // 如果 tailLength 为 0，调整 formerNum
75	    if (tailLength == 0 && formerNum > 0) {
76	        formerNum -= 1;
77	        tailLength = totalLength - formerNum * formerLength;
78	    }
79	
80	    // ---- UB 级 tiling (核内切分) ----
81	    // bufferCoefficient = 每元素在 UB 中总占用字节
82	    // 单输入单输出 + double buffer: 2 queues * 2(double buf) * dtypeSize = 4 * dtypeSize
83	    int64_t bufferCoefficient = dtypeSize * 4;
84	    if (bufferCoefficient == 0) { bufferCoefficient = 1; }
85	    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
86	    if (dtypeSize == 0) { dtypeSize = 1; }
87	    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
88	
89	    // 确保 tileLength 至少为 alignElements
90	    if (tileLength < alignElements) {
91	        tileLength = alignElements;
92	    }
93	
94	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
95	
96	    // ---- 准备 shape 和 stride 信息 ----
97	    int64_t ndim = self.dim();
98	    std::vector<int64_t> inputShapeVec(ndim);
99	    std::vector<int64_t> outputShapeVec(ndim);
100	    std::vector<int64_t> inputStrideVec(ndim);
101	    std::vector<int64_t> outputStrideVec(ndim);
102	
103	    // 计算输入 stride（行优先）
104	    for (int64_t i = ndim - 1; i >= 0; --i) {
105	        inputShapeVec[i] = inputSizes[i];
106	        outputShapeVec[i] = outputSizes[i];
107	        if (i == ndim - 1) {
108	            inputStrideVec[i] = 1;
109	            outputStrideVec[i] = 1;
110	        } else {
111	            inputStrideVec[i] = inputStrideVec[i + 1] * inputShapeVec[i + 1];
112	            outputStrideVec[i] = outputStrideVec[i + 1] * outputShapeVec[i + 1];
113	        }
114	    }
115	
116	    // 创建 shape/stride tensor 传入 kernel（确保在 NPU 设备上）
117	    auto cpuOptions = at::TensorOptions().dtype(at::kLong);
118	    auto inputShapeCpu = at::from_blob(inputShapeVec.data(), {ndim}, cpuOptions).clone();
119	    auto outputShapeCpu = at::from_blob(outputShapeVec.data(), {ndim}, cpuOptions).clone();
120	    auto inputStrideCpu = at::from_blob(inputStrideVec.data(), {ndim}, cpuOptions).clone();
121	    auto outputStrideCpu = at::from_blob(outputStrideVec.data(), {ndim}, cpuOptions).clone();
122	
123	    auto inputShapeTensor = inputShapeCpu.to(self.device());
124	    auto outputShapeTensor = outputShapeCpu.to(self.device());
125	    auto inputStrideTensor = inputStrideCpu.to(self.device());
126	    auto outputStrideTensor = outputStrideCpu.to(self.device());
127	
128	    // ---- 所有参数必须是左值 ----
129	    int64_t inputTotalLengthLval = inputTotalLength;
130	    int64_t outputTotalLengthLval = outputTotalLength;
131	    int64_t formerNumLval = formerNum;
132	    int64_t formerLengthLval = formerLength;
133	    int64_t tailLengthLval = tailLength;
134	    int64_t tileLengthLval = tileLength;
135	    int64_t dtypeSizeLval = dtypeSize;
136	    int64_t ndimLval = ndim;
137	
138	    EXEC_KERNEL_CMD(repeat, blockDim,
139	                    self, output,
140	                    inputTotalLengthLval, outputTotalLengthLval,
141	                    formerNumLval, formerLengthLval, tailLengthLval, tileLengthLval, dtypeSizeLval, ndimLval,
142	                    inputShapeTensor, outputShapeTensor, inputStrideTensor, outputStrideTensor);
143	
144	    return output;
145	}
